    x = x + 1;
}

int main(void) {
    int a = 5;
    incr(a);
    printf("%d\n", a);
    return 0;
}
```

Que vaut `carre(3) + carre(4)` ?
```c
int carre(int x) {
    return x * x;
}
```

Qu'affiche ce programme ?
```c
void raz(int t[], int n) {
    for (int i = 0; i < n; i++)
        t[i] = 0;
}

int main(void) {
    int a[3] = {1, 2, 3};
    raz(a, 3);
    printf("%d\n", a[1]);
    return 0;
}
```

Que vaut `h(10)` ?
```c
int h(int n) {
    for (int i = 0; i < n; i++)
        if (i * i > n)
            return i;
    return -1;
}
```

Exprime `g(x)` en fonction de `x` :
```c
double f(double x) {
    return 2 * x + 1;
}

double g(double x) {
    return f(f(x));
}
```

On veut échanger deux entiers. Où est l'erreur ?
```c
void echange(int a, int b) {
    int t = a;
    a = b;
    b = t;
}
```

Qu'affiche ce code ?
```c
int carre(int x) {
    return x * x;
}

printf("%d\n", carre(3) + carre(-2));
```

Qu'affiche ce code ?
```c
int t[5] = {1, 2, 3};
printf("%d\n", t[3] + t[4]);
```

Qu'affiche ce code ?
```c
int compteur(void) {
    static int n = 0;
    n++;
    return n;
}

compteur();
compteur();
printf("%d\n", compteur());
```

