#include <stdio.h>

int main(void) {
    int t[100], n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d", &t[i]);
    printf("%d\n", maximum(t, n));
    return 0;
}

exercices.solution:
int maximum(int t[], int n) {
    int max = t[0];
    for (int i = 1; i < n; i++)
        if (t[i] > max)
            max = t[i];
    return max;
}

