#include <stdio.h>

int main(void) {
    int t[100], n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d", &t[i]);
    inverser(t, n);
    for (int i = 0; i < n; i++)
        printf("%d ", t[i]);
    printf("\n");
    return 0;
}

exercices.solution:
void inverser(int t[], int n) {
    for (int i = 0; i < n / 2; i++) {
        int tmp = t[i];
        t[i] = t[n - 1 - i];
        t[n - 1 - i] = tmp;
    }
}
